import unittest

from pycparser import c_ast, c_parser


class CallCollector(c_ast.NodeVisitor):
    def __init__(self):
        self.names = []

    def visit_FuncCall(self, node):
        self.names.append(node.name.name)
        self.generic_visit(node)

    def visit_IfStmt(self, node):
        # Manually visit the condition
        self.visit(node.cond)

        # Visit the 'if' branch
        if node.if_stmt:
            self.visit(node.if_stmt)

        # Visit the 'else' branch
        if node.else_stmt:
            self.visit(node.else_stmt)

        # Call generic_visit to allow other potential traversals on IfStmt itself
        self.generic_visit(node)


class TestVisitorElse(unittest.TestCase):
    def test_visitor_visits_else_branch(self):
        # Test case: void f(int x) { if (x) a(); else b(); }
        ast = c_parser.CParser().parse("void f(int x) { if (x) a(); else b(); }")
        v = CallCollector()
        v.visit(ast)
        # Expect both 'a' (from if_stmt) and 'b' (from else_stmt) to be found
        self.assertEqual(v.names, ["a", "b"])
